def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    parts = s.split('.')
    version = []
    for part in parts:
        if part.isdigit():
            version.append(int(part))
        elif part.lstrip('-').isdigit():
            version.append(-int(part))
        else:
            break
    return tuple(version)

