from typing import Callable, Dict, Tuple, Any, Hashable, TypeVar, Generic

T = TypeVar('T')

class TTLCache(Generic[T]):
    def __init__(self, maxsize: int, ttl: float, timer: Callable[[], float], typed: bool):
        self.cache: Dict[Tuple[Hashable, ...], T] = {}
        self.expirations: Dict[Tuple[Hashable, ...], float] = {}
        self.ttl: float = ttl
        self.maxsize: int = maxsize
        self.timer: Callable[[], float] = timer
        self.typed: bool = typed

    def __getitem__(self, key: Tuple[Hashable, ...]) -> T:
        if key not in self.cache:
            raise KeyError(key)
        if self.is_expired(key):
            del self.cache[key]
            del self.expirations[key]
            raise KeyError(key)
        return self.cache[key]

    def __setitem__(self, key: Tuple[Hashable, ...], value: T) -> None:
        if len(self.cache) >= self.maxsize:
            oldest_key = min(self.expirations, key=self.expirations.get)
            del self.cache[oldest_key]
            del self.expirations[oldest_key]
        self.cache[key] = value
        self.expirations[key] = self.timer() + self.ttl

    def __contains__(self, key: Tuple[Hashable, ...]) -> bool:
        if key not in self.cache:
            return False
        if self.is_expired(key):
            del self.cache[key]
            del self.expirations[key]
            return False
        return True

    def is_expired(self, key: Tuple[Hashable, ...]) -> bool:
        return self.timer() >= self.expirations.get(key, 0)

    def clear(self) -> None:
        self.cache.clear()
        self.expirations.clear()

def ttl_cache(maxsize: int = 128, ttl: float = 600, timer: Callable[[], float] = time.monotonic, typed: bool = False):
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        cache = TTLCache(maxsize, ttl, timer, typed)

        def wrapper(*args: Any, **kwargs: Any) -> T:
            key = args if not typed else (type(arg) if isinstance(arg, dict) else arg for arg in args) + tuple(kwargs.items())
            try:
                return cache[key]
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = value
                return value

        return wrapper

    return decorator

