def format_sql(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :param params: The set of in-style parameters. It maps each parameter
                    to value.
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    """
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    if self.SQLParams.in_style == 'named':
        out_params = {}
        for k, v in params.items():
            out_params[f'${k}'] = v
        formatted_sql = sql.format(**out_params)
    else:
        formatted_sql = sql
        out_params = list(params)

    return formatted_sql, out_params

