def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    inventory_version = None
    if extract_spec_version:
        if 'type' in inventory:
            inventory_version = inventory['type']

    if inventory_version is None or inventory_version not in self.supported_versions:
        inventory_version = self.spec_version

    for key, value in inventory.items():
        if key in self.schema:
            field_schema = self.schema[key]
            if 'type' in field_schema:
                field_type = field_schema['type']
                if field_type != type(value) and field_type != isinstance(field_type, Schema):
                    raise ValueError(f"Invalid type for {key}. Expected {field_type}, but got {type(value)}")

    if not extract_spec_version:
        return

    if 'type' in inventory and inventory['type'] not in self.supported_versions:
        raise ValueError(f"Unsupported specification version: {inventory['type']}")

