def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Input must be an InventoryValidator object")

    if self.version != prior.version:
        raise ValueError("Prior version ({}) does not match current version ({})".format(prior.version, self.version))

    if not all(label in prior.inventory for label in self.inventory):
        raise ValueError("Prior inventory does not contain all labels from the current inventory")

    for label in self.inventory:
        if self.inventory[label].shape != prior.inventory[label].shape:
            raise ValueError("Shape mismatch for label {} between current and prior inventory".format(label))

    if not all(self.inventory[label].equals(prior.inventory[label]) for label in self.inventory):
        raise ValueError("Data mismatch for label {} between current and prior inventory".format(label))

