def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if expr.type == 'binary':
            if expr.op == '&':
                if expr.left.type == 'binary' and expr.left.op == '|':
                    if expr.left.left == expr:
                        return expr.left.right
                if expr.right.type == 'binary' and expr.right.op == '|':
                    if expr.right.left == expr:
                        return expr.right.right
            if expr.op == '|':
                if expr.left.type == 'binary' and expr.left.op == '&':
                    if expr.left.left == expr:
                        return expr.left.right
                if expr.right.type == 'binary' and expr.right.op == '&':
                    if expr.right.left == expr:
                        return expr.right.right
        if expr.type == 'unary' and expr.op == '&':
            if expr.right.type == 'binary' and expr.right.op == '|':
                if expr.right.left.type == 'unary' and expr.right.left.op == '~' and expr.right.left.right == expr:
