            if expr.right.type == 'binary' and expr.right.op == '&':
                if expr.right.left.type == 'unary' and expr.right.left.op == '~' and expr.right.left.right == expr:
                    return expr.right.right
        return expr

    return [apply_absorption(expr) for expr in args]

