def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    command = [commands] + args
    try:
        if verbose:
            if hide_stderr:
                output = subprocess.check_output(command, stderr=subprocess.STDOUT, cwd=cwd, env=env, text=True)
            else:
                output = subprocess.check_output(command, cwd=cwd, env=env, text=True)
            print(output)
        else:
            subprocess.check_call(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL if hide_stderr else subprocess.STDOUT, cwd=cwd, env=env)
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            error_message = f"Error running command: {command} - Output: {e.output.decode()}"
        else:
            error_message = f"Error running command: {command} - Output: {e.output.decode()}"
        raise Exception(error_message)

