def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    for attr_name in iface.__dict__.keys():
        attr = getattr(iface, attr_name)
        if not callable(attr):
            continue
        if attr_name not in candidate.__dict__:
            if not tentative:
                raise AttributeError(f"{candidate} does not have attribute {attr_name}")
        else:
            candidate_attr = getattr(candidate, attr_name)
            if not callable(candidate_attr):
                raise AttributeError(f"{candidate} attribute {attr_name} is not callable")
            if not attr.im_func == candidate_attr.im_func:
                if not tentative:
                    raise AttributeError(f"{candidate} attribute {attr_name} does not match {iface}")

